#include <iostream>
#include <string>
#include <vector>

struct Formula {
    std::string name;
    std::function<bool(bool, bool, bool)> eval;
};

bool implies(bool a, bool b) { return !a || b; }

std::string tf(bool b) { return b ? "T" : "F"; }

int main() {
    const std::vector<Formula> formulas = {
        {"(p|q)->r", [](bool p, bool q, bool r) { return implies(p || q, r); }},
        {"((p->q)&(q->r))->(p->r)",
         [](bool p, bool q, bool r) { return implies(implies(p, q) && implies(q, r), implies(p, r)); }},
        {"p&~p", [](bool p, bool, bool) { return p && !p; }},
    };

    const int rows = 1 << 3;  // n variables give 2^n rows
    std::vector<int> trueCount(formulas.size(), 0);
    const std::vector<std::string> gaps = {"    ", "                 ", "              "};
    std::cout << "p q r | (p|q)->r  ((p->q)&(q->r))->(p->r)  p&~p\n";
    for (int i = 0; i < rows; i++) {
        // Read the row number in binary: p is the high bit, r the low bit
        bool p = i & 4, q = i & 2, r = i & 1;
        std::string line = tf(p) + " " + tf(q) + " " + tf(r) + " |";
        for (size_t k = 0; k < formulas.size(); k++) {
            bool v = formulas[k].eval(p, q, r);
            if (v) trueCount[k]++;
            line += gaps[k] + tf(v);
        }
        std::cout << line << "\n";
    }
    for (size_t k = 0; k < formulas.size(); k++) {
        std::string kind = trueCount[k] == rows ? "tautology" : trueCount[k] == 0 ? "contradiction" : "contingency";
        std::cout << formulas[k].name << ": true in " << trueCount[k] << " of " << rows << " rows -> " << kind
                  << "\n";
    }
}

