            converseMatches = converseMatches && imp == converse;
            inverseMatchesConverse = inverseMatchesConverse && inverse == converse;
            std::string note = imp ? "" : "   <- the only row where p->q is false";
            std::cout << tf(p) << " " << tf(q) << " |  " << tf(imp) << "     " << tf(converse) << "      "
