// Check equivalences by evaluating both sides on every row of the truth table
#include <cstdio>
#include <functional>
#include <iostream>
#include <optional>
#include <string>
#include <vector>

using Formula3 = std::function<bool(bool, bool, bool)>;

struct Pair {
    std::string left;
    Formula3 a;
    std::string right;
    Formula3 b;
};

bool implies(bool x, bool y) { return !x || y; }

std::string tf(bool b) { return b ? "T" : "F"; }

// Empty if A and B agree on all 8 rows, otherwise describes the first row that differs
std::optional<std::string> firstCounterexample(const Formula3& a, const Formula3& b) {
    for (int i = 0; i < 8; i++) {
        bool p = i & 4, q = i & 2, r = i & 1;
        bool x = a(p, q, r), y = b(p, q, r);
        if (x != y) return "p=" + tf(p) + " q=" + tf(q) + " r=" + tf(r) + " gives " + tf(x) + " vs " + tf(y);
    }
    return std::nullopt;
}

int main() {
    // De Morgan, shown row by row first
    std::cout << "p q | ~(p&q)  ~p|~q\n";
    for (int i = 0; i < 4; i++) {
        bool p = i & 2, q = i & 1;
        std::cout << tf(p) << " " << tf(q) << " |    " << tf(!(p && q)) << "      " << tf(!p || !q) << "\n";
    }

    const std::vector<Pair> pairs = {
        {"~(p&q)", [](bool p, bool q, bool) { return !(p && q); }, "~p|~q", [](bool p, bool q, bool) { return !p || !q; }},
        {"~(p|q)", [](bool p, bool q, bool) { return !(p || q); }, "~p&~q", [](bool p, bool q, bool) { return !p && !q; }},
        {"p->q", [](bool p, bool q, bool) { return implies(p, q); }, "~p|q", [](bool p, bool q, bool) { return !p || q; }},
        {"p&(q|r)", [](bool p, bool q, bool r) { return p && (q || r); },
         "(p&q)|(p&r)", [](bool p, bool q, bool r) { return (p && q) || (p && r); }},
        {"~(p&q)", [](bool p, bool q, bool) { return !(p && q); }, "~p&~q", [](bool p, bool q, bool) { return !p && !q; }},
        {"p->(q->r)", [](bool p, bool q, bool r) { return implies(p, implies(q, r)); },
         "(p->q)->r", [](bool p, bool q, bool r) { return implies(implies(p, q), r); }},
    };
    for (const auto& pair : pairs) {
        auto bad = firstCounterexample(pair.a, pair.b);
        std::string verdict = bad ? "NOT equivalent: " + *bad : "equivalent (all 8 rows agree)";
        std::printf("%-9s vs %-11s : %s\n", pair.left.c_str(), pair.right.c_str(), verdict.c_str());
    }
}

