// Sets, relations, and functions mini demo
import java.util.*;

public class SetsRelationsFunctions {
    // TreeSet keeps elements sorted, so the printout is predictable
    static String show(Collection<Integer> s) {
        StringJoiner j = new StringJoiner(", ", "{", "}");
        for (int x : s) j.add(String.valueOf(x));
        return j.toString();
    }

    static boolean isInjective(Map<Integer, Integer> f) {
        Set<Integer> seen = new HashSet<>();
        for (int value : f.values()) {
            if (!seen.add(value)) return false; // two inputs share an output
        }
        return true;
    }

    static boolean isSurjective(Map<Integer, Integer> f, Set<Integer> codomain) {
        return new HashSet<>(f.values()).containsAll(codomain);
    }

    // The relation R is "x <= y"; any other predicate could be tested the same way
    static boolean leq(int x, int y) {
        return x <= y;
    }

    static String yesNo(boolean b) {
        return b ? "yes" : "no";
    }

    public static void main(String[] args) {
        Set<Integer> a = new TreeSet<>(List.of(1, 2, 3));
        Set<Integer> b = new TreeSet<>(List.of(3, 4, 5));
        Set<Integer> intersection = new TreeSet<>(a);
        intersection.retainAll(b);
        Set<Integer> union = new TreeSet<>(a);
        union.addAll(b);
        Set<Integer> difference = new TreeSet<>(a);
        difference.removeAll(b);
        System.out.println("A = " + show(a) + ", B = " + show(b));
        System.out.println("A intersect B = " + show(intersection));
        System.out.println("A union B     = " + show(union));
        System.out.println("A minus B     = " + show(difference));
        System.out.println("|A union B| = |A| + |B| - |A intersect B| = " + a.size() + " + " + b.size() + " - "
                + intersection.size() + " = " + union.size());
        System.out.println("|A x B| = " + a.size() + " * " + b.size() + " = " + a.size() * b.size() + " pairs");

        // Each bit of mask decides whether one element is in the subset
        List<Integer> elems = new ArrayList<>(a);
        StringJoiner subsets = new StringJoiner(" ");
        for (int mask = 0; mask < (1 << elems.size()); mask++) {
            List<Integer> sub = new ArrayList<>();
            for (int i = 0; i < elems.size(); i++) {
                if ((mask & (1 << i)) != 0) sub.add(elems.get(i));
            }
            subsets.add(show(sub));
        }
        System.out.println("P(A) has 2^3 = " + (1 << elems.size()) + " subsets: " + subsets);

        // The relation <= on A, checked straight from the definitions
        boolean reflexive = true, antisymmetric = true, transitive = true;
        for (int x : a) {
            reflexive &= leq(x, x);
            for (int y : a) {
                if (leq(x, y) && leq(y, x) && x != y) antisymmetric = false;
                for (int z : a) {
                    if (leq(x, y) && leq(y, z) && !(leq(x, z))) transitive = false;
                }
            }
        }
        System.out.println("<= on A: reflexive=" + yesNo(reflexive) + " antisymmetric=" + yesNo(antisymmetric)
                + " transitive=" + yesNo(transitive) + " -> partial order");

        Map<Integer, Integer> f = new TreeMap<>(Map.of(1, 10, 2, 20, 3, 30));
        Set<Integer> codomain = new TreeSet<>(List.of(10, 20, 30));
        System.out.println("f = {1->10, 2->20, 3->30}: injective? " + yesNo(isInjective(f))
                + ", onto " + show(codomain) + "? " + yesNo(isSurjective(f, codomain)));
    }
}

