import java.util.*;

// Union, intersection, difference and complement with Java's bulk Set operations
public class SetOperationsDemo {
    static String show(Set<Integer> s) {
        StringJoiner j = new StringJoiner(", ", "{", "}");
        for (int x : s) j.add(String.valueOf(x));
        return j.toString();
    }

    // Copy first: addAll/retainAll/removeAll modify the set they are called on
    static Set<Integer> union(Set<Integer> a, Set<Integer> b) {
        Set<Integer> r = new TreeSet<>(a);
        r.addAll(b);
        return r;
    }

    static Set<Integer> intersect(Set<Integer> a, Set<Integer> b) {
        Set<Integer> r = new TreeSet<>(a);
        r.retainAll(b);
        return r;
    }

    static Set<Integer> minus(Set<Integer> a, Set<Integer> b) {
        Set<Integer> r = new TreeSet<>(a);
        r.removeAll(b);
        return r;
    }

    public static void main(String[] args) {
        Set<Integer> u = new TreeSet<>(), a = new TreeSet<>(), b = new TreeSet<>();
        for (int x = 1; x <= 10; x++) {
            u.add(x);
            if (x % 2 == 0) a.add(x);
            if (x % 3 == 0) b.add(x);
        }
        Set<Integer> notA = minus(u, a); // the complement is relative to the universe U
        System.out.println("U               = " + show(u));
        System.out.println("A (even)        = " + show(a));
        System.out.println("B (mult. of 3)  = " + show(b));
        System.out.println("A union B       = " + show(union(a, b)));
        System.out.println("A intersect B   = " + show(intersect(a, b)));
        System.out.println("A \\ B           = " + show(minus(a, b)));
        System.out.println("B \\ A           = " + show(minus(b, a)));
        System.out.println("complement of A = " + show(notA));
        System.out.println("A sym diff B    = " + show(union(minus(a, b), minus(b, a))));
        System.out.println("inclusion-exclusion: " + a.size() + " + " + b.size() + " - " + intersect(a, b).size()
                + " = " + union(a, b).size() + " = |A union B|");
        Set<Integer> left = minus(u, union(a, b));
        Set<Integer> right = intersect(notA, minus(u, b));
        System.out.println("De Morgan: U \\ (A union B) = " + show(left) + ", (U \\ A) intersect (U \\ B) = "
                + show(right) + ", equal: " + left.equals(right));
    }
}

