// Union, intersection, difference and complement with the <algorithm> set functions
#include <algorithm>
#include <iostream>
#include <iterator>
#include <set>
#include <string>

using IntSet = std::set<int>;

std::string show(const IntSet& s) {
    std::string out = "{";
    for (int x : s) out += (out.size() > 1 ? ", " : "") + std::to_string(x);
    return out + "}";
}

// The std::set_* algorithms need sorted input, which std::set guarantees
IntSet unite(const IntSet& a, const IntSet& b) {
    IntSet r;
    std::set_union(a.begin(), a.end(), b.begin(), b.end(), std::inserter(r, r.end()));
    return r;
}

IntSet intersect(const IntSet& a, const IntSet& b) {
    IntSet r;
    std::set_intersection(a.begin(), a.end(), b.begin(), b.end(), std::inserter(r, r.end()));
    return r;
}

IntSet minus(const IntSet& a, const IntSet& b) {
    IntSet r;
    std::set_difference(a.begin(), a.end(), b.begin(), b.end(), std::inserter(r, r.end()));
    return r;
}

int main() {
    IntSet u, a, b;
    for (int x = 1; x <= 10; x++) {
        u.insert(x);
        if (x % 2 == 0) a.insert(x);
        if (x % 3 == 0) b.insert(x);
    }
    IntSet notA = minus(u, a);  // the complement is relative to the universe U
    std::cout << "U               = " << show(u) << "\n";
    std::cout << "A (even)        = " << show(a) << "\n";
    std::cout << "B (mult. of 3)  = " << show(b) << "\n";
    std::cout << "A union B       = " << show(unite(a, b)) << "\n";
    std::cout << "A intersect B   = " << show(intersect(a, b)) << "\n";
    std::cout << "A \\ B           = " << show(minus(a, b)) << "\n";
    std::cout << "B \\ A           = " << show(minus(b, a)) << "\n";
    std::cout << "complement of A = " << show(notA) << "\n";
    std::cout << "A sym diff B    = " << show(unite(minus(a, b), minus(b, a))) << "\n";
    std::cout << "inclusion-exclusion: " << a.size() << " + " << b.size() << " - " << intersect(a, b).size()
              << " = " << unite(a, b).size() << " = |A union B|\n";
    IntSet left = minus(u, unite(a, b));
    IntSet right = intersect(notA, minus(u, b));
    std::cout << "De Morgan: U \\ (A union B) = " << show(left) << ", (U \\ A) intersect (U \\ B) = " << show(right)
              << ", equal: " << (left == right ? "true" : "false") << "\n";
}

