import java.util.ArrayList;
import java.util.List;

// The Cartesian product A x B: every ordered pair (a, b) with a from A and b from B
public class CartesianProductDemo {
    record Pair(String first, String second) {
        @Override
        public String toString() {
            return "(" + first + ", " + second + ")";
        }
    }

    // Nested loops: the outer element is always the first coordinate
    static List<Pair> product(List<String> a, List<String> b) {
        List<Pair> result = new ArrayList<>();
        for (String x : a) {
            for (String y : b) result.add(new Pair(x, y));
        }
        return result;
    }

    static String show(List<Pair> pairs) {
        List<String> parts = new ArrayList<>();
        for (Pair p : pairs) parts.add(p.toString());
        return "{" + String.join(", ", parts) + "}";
    }

    public static void main(String[] args) {
        List<String> a = List.of("1", "2", "3");
        List<String> b = List.of("x", "y");
        List<Pair> ab = product(a, b);
        List<Pair> ba = product(b, a);
        System.out.println("A = {1, 2, 3}, B = {x, y}");
        System.out.println("A x B = " + show(ab));
        System.out.println("|A x B| = " + ab.size() + " = |A| * |B| = " + a.size() + " * " + b.size());
        System.out.println("B x A = " + show(ba));
        // Pairs are ordered, so (1, x) and (x, 1) are different objects
        Pair p = new Pair("1", "x");
        System.out.println(p + " in A x B: " + ab.contains(p) + ", in B x A: " + ba.contains(p)
                + " -> A x B != B x A");

        int cells = product(a, a).size();
        System.out.println("A x A has " + cells + " pairs, so A has 2^" + cells + " = " + (1 << cells)
                + " relations (subsets of A x A)");
        List<String> four = List.of("1", "2", "3", "4");
        List<String> five = List.of("a", "b", "c", "d", "e");
        System.out.println("check: |{1..4} x {a..e}| = " + product(four, five).size() + " = 4 * 5");
    }
}

