              << " relations (subsets of A x A)\n";
    const std::vector<std::string> four = {"1", "2", "3", "4"};
    const std::vector<std::string> five = {"a", "b", "c", "d", "e"};
    std::cout << "check: |{1..4} x {a..e}| = " << product(four, five).size() << " = 4 * 5\n";
}

