import java.util.*;
import java.util.function.BiPredicate;

// Test reflexive / symmetric / antisymmetric / transitive on small relations over A = {1, 2, 3, 4}
public class RelationProperties {
    static final int[] A = {1, 2, 3, 4};

    static String yesNo(boolean b) {
        return b ? "yes" : "no";
    }

    static void analyze(String name, BiPredicate<Integer, Integer> r) {
        List<String> pairs = new ArrayList<>();
        for (int x : A) for (int y : A) if (r.test(x, y)) pairs.add("(" + x + "," + y + ")");
        System.out.println(name + ": {" + String.join(", ", pairs) + "}");

        boolean refl = true, sym = true, anti = true, trans = true;
        String witness = null;
        for (int x : A) {
            if (!r.test(x, x)) refl = false;
            for (int y : A) {
                if (r.test(x, y) && !r.test(y, x)) sym = false;
                if (r.test(x, y) && r.test(y, x) && x != y) anti = false;
                for (int z : A) {
                    // Transitivity needs (x,z) whenever (x,y) and (y,z) are both present
                    if (r.test(x, y) && r.test(y, z) && !r.test(x, z)) {
                        if (trans) witness = "(" + x + "," + y + ") and (" + y + "," + z + ") are in R but ("
                                + x + "," + z + ") is not";
                        trans = false;
                    }
                }
            }
        }
        String kind = refl && sym && trans ? "equivalence relation"
                : refl && anti && trans ? "partial order" : "neither";
        System.out.println("  reflexive=" + yesNo(refl) + " symmetric=" + yesNo(sym) + " antisymmetric="
                + yesNo(anti) + " transitive=" + yesNo(trans) + " -> " + kind);
        if (witness != null) System.out.println("  not transitive: " + witness);
        if (kind.equals("equivalence relation")) {
            // Each element's related set is its class; the classes partition A
            Set<Integer> seen = new TreeSet<>();
            List<String> classes = new ArrayList<>();
            for (int x : A) {
                if (seen.contains(x)) continue;
                List<String> cls = new ArrayList<>();
                for (int y : A) if (r.test(x, y)) { cls.add(String.valueOf(y)); seen.add(y); }
                classes.add("{" + String.join(", ", cls) + "}");
            }
            System.out.println("  classes: " + String.join(" ", classes));
        }
    }

    public static void main(String[] args) {
        analyze("same parity", (x, y) -> (x - y) % 2 == 0);
        analyze("divides", (x, y) -> y % x == 0);
        analyze("less than", (x, y) -> x < y);
        analyze("R", (x, y) -> (x == 1 && y == 2) || (x == 2 && y == 1));
    }
}

