#include <vector>

const std::vector<int> A = {1, 2, 3, 4};
using Relation = std::function<bool(int, int)>;

std::string yesNo(bool b) { return b ? "yes" : "no"; }

std::string pairText(int x, int y) { return "(" + std::to_string(x) + "," + std::to_string(y) + ")"; }

void analyze(const std::string& name, const Relation& r) {
    std::string pairs;
    for (int x : A)
        for (int y : A)
            if (r(x, y)) pairs += (pairs.empty() ? "" : ", ") + pairText(x, y);
    std::cout << name << ": {" << pairs << "}\n";

    bool refl = true, sym = true, anti = true, trans = true;
    std::string witness;
    for (int x : A) {
        if (!r(x, x)) refl = false;
        for (int y : A) {
            if (r(x, y) && !r(y, x)) sym = false;
            if (r(x, y) && r(y, x) && x != y) anti = false;
            for (int z : A) {
                // Transitivity needs (x,z) whenever (x,y) and (y,z) are both present
                if (r(x, y) && r(y, z) && !r(x, z)) {
                    if (trans) witness = pairText(x, y) + " and " + pairText(y, z) + " are in R but " +
                                         pairText(x, z) + " is not";
                    trans = false;
                }
            }
        }
    }
    std::string kind = refl && sym && trans ? "equivalence relation" : refl && anti && trans ? "partial order" : "neither";
    std::cout << "  reflexive=" << yesNo(refl) << " symmetric=" << yesNo(sym) << " antisymmetric=" << yesNo(anti)
              << " transitive=" << yesNo(trans) << " -> " << kind << "\n";
    if (!witness.empty()) std::cout << "  not transitive: " << witness << "\n";
    if (kind == "equivalence relation") {
        // Each element's related set is its class; the classes partition A
        std::set<int> seen;
        std::string classes;
        for (int x : A) {
            if (seen.count(x)) continue;
            std::string cls;
            for (int y : A) {
                if (r(x, y)) {
                    cls += (cls.empty() ? "" : ", ") + std::to_string(y);
                    seen.insert(y);
                }
            }
            classes += (classes.empty() ? "{" : " {") + cls + "}";
        }
        std::cout << "  classes: " << classes << "\n";
    }
}

int main() {
    analyze("same parity", [](int x, int y) { return (x - y) % 2 == 0; });
    analyze("divides", [](int x, int y) { return y % x == 0; });
    analyze("less than", [](int x, int y) { return x < y; });
    analyze("R", [](int x, int y) { return (x == 1 && y == 2) || (x == 2 && y == 1); });
}

