  }
  if (kind === 'equivalence relation') {
    // Each element's related set is its class; the classes partition A
    const seen = new Set();
    const classes = [];
    for (const x of A) {
      if (seen.has(x)) continue;
      const cls = A.filter((y) => r(x, y));
      cls.forEach((y) => seen.add(y));
      classes.push(`{${cls.join(', ')}}`);
    }
    console.log(`  classes: ${classes.join(' ')}`);
  }
}

