import java.util.*;

// Campus map: buildings are vertices, footpaths are undirected edges
public class CampusGraph {
    static final String[][] EDGES = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}};
    static final Map<String, List<String>> adj = new TreeMap<>();

    static void dfs(String u, Set<String> seen, List<String> order) {
        seen.add(u);
        order.add(u);
        for (String w : adj.get(u)) if (!seen.contains(w)) dfs(w, seen, order);
    }

    public static void main(String[] args) {
        for (String[] e : EDGES) {
            adj.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
            adj.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
        }
        for (List<String> list : adj.values()) Collections.sort(list); // alphabetical neighbors
        List<String> verts = new ArrayList<>(adj.keySet());

        System.out.println("Adjacency list:");
        int degreeSum = 0;
        for (String v : verts) {
            System.out.println("  " + v + ": " + String.join(" ", adj.get(v)));
            degreeSum += adj.get(v).size();
        }
        System.out.println("Sum of degrees = " + degreeSum + " = 2 * " + EDGES.length + " edges");

        Map<String, Integer> dist = new HashMap<>();
        List<String> order = new ArrayList<>();
        Deque<String> queue = new ArrayDeque<>();
        dist.put("A", 0);
        queue.add("A");
        while (!queue.isEmpty()) {
            String u = queue.poll();
            order.add(u);
            for (String w : adj.get(u)) {
                if (!dist.containsKey(w)) {
                    dist.put(w, dist.get(u) + 1);
                    queue.add(w);
                }
            }
        }
        System.out.println("BFS from A: " + String.join(" ", order));
        List<String> parts = new ArrayList<>();
        for (String v : verts) parts.add(v + "=" + dist.get(v));
        System.out.println("Edges from A: " + String.join(", ", parts));
        List<String> dfsOrder = new ArrayList<>();
        dfs("A", new HashSet<>(), dfsOrder);
        System.out.println("DFS from A: " + String.join(" ", dfsOrder));
        boolean connected = order.size() == verts.size();
        System.out.println("Connected: " + (connected ? "yes" : "no"));
        boolean isTree = connected && EDGES.length == verts.size() - 1;
        System.out.println("Tree: " + (isTree ? "yes" : "no") + " (" + EDGES.length + " edges; a tree on " + verts.size() + " vertices has " + (verts.size() - 1) + ")");
    }
}

