using namespace std;

// Every simple path from A to F, the shortest one, and a cycle found by depth-first search
map<string, vector<string>> adj;
map<string, string> parentOf;

string join(const vector<string>& items, const string& sep) {
    string out;
    for (size_t i = 0; i < items.size(); i++) out += (i ? sep : "") + items[i];
    return out;
}

void allPaths(const string& u, const string& target, vector<string>& path, vector<vector<string>>& found) {
    if (u == target) {
        found.push_back(path);
        return;
    }
    for (const string& w : adj[u]) {
        if (find(path.begin(), path.end(), w) == path.end()) { // a path never repeats a vertex
            path.push_back(w);
            allPaths(w, target, path, found);
            path.pop_back();
        }
    }
}

// In an undirected DFS, reaching an already-visited vertex other than your parent closes a cycle
vector<string> findCycle(const string& u, const string& p) {
    parentOf[u] = p;
    for (const string& w : adj[u]) {
        if (w == p) continue;
        if (parentOf.count(w)) {
            vector<string> cycle = {u};
            string x = u;
            while (x != w) {
                x = parentOf[x];
                cycle.push_back(x);
            }
            return cycle;
        }
        vector<string> found = findCycle(w, u);
        if (!found.empty()) return found;
    }
    return {};
}

int main() {
    vector<pair<string, string>> edges = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}};
    for (auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (auto& [v, list] : adj) sort(list.begin(), list.end());

    vector<vector<string>> paths;
    vector<string> start = {"A"};
    allPaths("A", "F", start, paths);
    cout << "Simple paths from A to F: " << paths.size() << "\n";
    for (auto& p : paths) cout << "  " << join(p, " -> ") << "  (length " << p.size() - 1 << ")\n";
    vector<string> shortest = paths[0];
    for (auto& p : paths) if (p.size() < shortest.size()) shortest = p;
    cout << "Shortest: " << join(shortest, " -> ") << " with " << shortest.size() - 1 << " edges\n";

    vector<string> cycle = findCycle("A", "");
    vector<string> closed = cycle;
    closed.push_back(cycle[0]);
    cout << "Cycle found: " << join(closed, " -> ") << " (length " << cycle.size() << ")\n";
    cout << "A walk may repeat vertices: A -> B -> A -> C is a walk, not a path\n";
}

