#include <algorithm>
#include <iostream>
#include <map>
#include <queue>
#include <set>
#include <string>
#include <vector>
using namespace std;

// Connected components with BFS, and bridges: edges whose removal disconnects the graph
using Edge = pair<string, string>;

vector<vector<string>> components(const vector<string>& verts, const vector<Edge>& edges) {
    map<string, vector<string>> adj;
    for (auto& v : verts) adj[v];
    for (auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    set<string> seen;
    vector<vector<string>> comps;
    for (auto& s : verts) {
        if (seen.count(s)) continue;
        vector<string> comp;
        queue<string> q;
        q.push(s);
        seen.insert(s);
        while (!q.empty()) {
            string u = q.front();
            q.pop();
            comp.push_back(u);
            vector<string> next = adj[u];
            sort(next.begin(), next.end());
            for (auto& w : next) {
                if (seen.insert(w).second) q.push(w);
            }
        }
        sort(comp.begin(), comp.end());
        comps.push_back(comp);
    }
    return comps;
}

string join(const vector<string>& items, const string& sep) {
    string out;
    for (size_t i = 0; i < items.size(); i++) out += (i ? sep : "") + items[i];
    return out;
}

string show(const vector<vector<string>>& comps) {
    vector<string> parts;
    for (auto& c : comps) parts.push_back("{" + join(c, ", ") + "}");
    return join(parts, "  ");
}

int main() {
    vector<string> verts = {"A", "B", "C", "D", "E", "F", "G", "H"};
    vector<Edge> edges = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}, {"G", "H"}};
    auto comps = components(verts, edges);
    cout << comps.size() << " components: " << show(comps) << "\n";
    cout << "Connected: " << (comps.size() == 1 ? "yes" : "no") << "\n";

    // Remove each edge of the big component in turn and count components again
