function components(verts, edges) {
  const adj = Object.fromEntries(verts.map((v) => [v, []]));
  for (const [u, v] of edges) {
    adj[u].push(v);
    adj[v].push(u);
  }
  const seen = new Set(), comps = [];
  for (const s of verts) {
