#include <algorithm>
#include <deque>
#include <iostream>
#include <map>
#include <set>
#include <string>
#include <vector>
using namespace std;

// BFS explores in rings using a queue; DFS goes deep first using a stack
string join(const deque<string>& items) {
    if (items.empty()) return "-";
    string out;
    for (size_t i = 0; i < items.size(); i++) out += (i ? " " : "") + items[i];
    return out;
}

int main() {
    vector<pair<string, string>> edges = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}};
    map<string, vector<string>> adj;
    for (auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (auto& [v, list] : adj) sort(list.begin(), list.end());

    cout << "BFS from A (queue = first in, first out):\n";
    map<string, int> dist = {{"A", 0}};
    deque<string> queue = {"A"};
    while (!queue.empty()) {
        string u = queue.front();
        queue.pop_front();
        for (auto& w : adj[u]) {
            if (!dist.count(w)) {
                dist[w] = dist[u] + 1;
                queue.push_back(w);
            }
        }
        cout << "  visit " << u << " (distance " << dist[u] << ")  queue now: " << join(queue) << "\n";
    }

    cout << "DFS from A (stack = last in, first out):\n";
    set<string> seen;
    deque<string> stack = {"A"}; // the back is the top
    deque<string> order;
    while (!stack.empty()) {
        string u = stack.back();
        stack.pop_back();
        if (seen.count(u)) continue;
        seen.insert(u);
        order.push_back(u);
        // push in reverse so the alphabetically first neighbor is explored first
        for (auto it = adj[u].rbegin(); it != adj[u].rend(); ++it) {
            if (!seen.count(*it)) stack.push_back(*it);
        }
        cout << "  visit " << u << "  stack now: " << join(stack) << "\n";
    }
    cout << "DFS order: " << join(order) << "\n";
    cout << "BFS gives shortest path lengths: F is " << dist["F"] << " edges from A\n";
}

