import java.util.*;

// A tree is connected with exactly n - 1 edges: one path between any two vertices, no cycles
public class TreeVsGraph {
    static final List<String> VERTS = List.of("A", "B", "C", "D", "E", "F");

    static List<String[]> edges(String... pairs) {
        List<String[]> out = new ArrayList<>();
        for (String p : pairs) out.add(new String[]{p.substring(0, 1), p.substring(1)});
        return out;
    }

    // Returns parent pointers; "found" collects the edge that discovered each vertex
    static Map<String, String> bfsParents(List<String[]> edges, String start, List<String> found) {
        Map<String, List<String>> adj = new HashMap<>();
        for (String v : VERTS) adj.put(v, new ArrayList<>());
        for (String[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        Map<String, String> parent = new HashMap<>();
        parent.put(start, null);
        Deque<String> queue = new ArrayDeque<>(List.of(start));
        while (!queue.isEmpty()) {
            String u = queue.poll();
            List<String> next = new ArrayList<>(adj.get(u));
            Collections.sort(next);
            for (String w : next) {
                if (!parent.containsKey(w)) {
                    parent.put(w, u);
                    found.add(u + "-" + w);
                    queue.add(w);
                }
            }
        }
        return parent;
    }

    static void check(String name, List<String[]> edges) {
        Map<String, String> parent = bfsParents(edges, "A", new ArrayList<>());
        boolean connected = parent.size() == VERTS.size();
        boolean tree = connected && edges.size() == VERTS.size() - 1;
        System.out.println(name + ": " + edges.size() + " edges, connected=" + (connected ? "yes" : "no") + " -> " + (tree ? "tree" : "not a tree"));
    }

    public static void main(String[] args) {
        List<String[]> tree = edges("AB", "AC", "BD", "BE", "CF");
        List<String[]> campus = edges("AB", "AC", "BD", "CD", "DE", "EF");
        check("T", tree);
        check("T without C-F", tree.subList(0, tree.size() - 1));
        check("Campus map", campus);

        // Adding any edge to a tree closes exactly one cycle: the tree path between its ends plus the new edge
        Map<String, String> parent = bfsParents(tree, "D", new ArrayList<>());
        List<String> path = new ArrayList<>();
        for (String x = "F"; x != null; x = parent.get(x)) path.add(x);
        Collections.reverse(path);
        System.out.println("Tree path D to F: " + String.join(" -> ", path));
        path.add("D");
        System.out.println("Adding D-F closes the cycle: " + String.join(" -> ", path));

        // BFS keeps only the edge that discovered each vertex: a spanning tree of the campus map
        List<String> spanning = new ArrayList<>();
        bfsParents(campus, "A", spanning);
        System.out.println("BFS spanning tree of the campus map: " + String.join(", ", spanning) + " (" + spanning.size() + " = " + VERTS.size() + " - 1 edges)");
    }
}

