using namespace std;

// A tree is connected with exactly n - 1 edges: one path between any two vertices, no cycles
using Edge = pair<string, string>;
const vector<string> VERTS = {"A", "B", "C", "D", "E", "F"};

string join(const vector<string>& items, const string& sep) {
    string out;
    for (size_t i = 0; i < items.size(); i++) out += (i ? sep : "") + items[i];
    return out;
}

// Returns parent pointers ("" for the start); "found" collects the edge that discovered each vertex
map<string, string> bfsParents(const vector<Edge>& edges, const string& start, vector<string>& found) {
    map<string, vector<string>> adj;
    for (auto& v : VERTS) adj[v];
    for (auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    map<string, string> parent = {{start, ""}};
    queue<string> q;
    q.push(start);
    while (!q.empty()) {
        string u = q.front();
        q.pop();
        vector<string> next = adj[u];
        sort(next.begin(), next.end());
        for (auto& w : next) {
            if (!parent.count(w)) {
                parent[w] = u;
                found.push_back(u + "-" + w);
                q.push(w);
            }
        }
    }
    return parent;
}

void check(const string& name, const vector<Edge>& edges) {
    vector<string> ignored;
    auto parent = bfsParents(edges, "A", ignored);
    bool connected = parent.size() == VERTS.size();
    bool tree = connected && edges.size() == VERTS.size() - 1;
    cout << name << ": " << edges.size() << " edges, connected=" << (connected ? "yes" : "no") << " -> " << (tree ? "tree" : "not a tree") << "\n";
}

int main() {
    vector<Edge> tree = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"B", "E"}, {"C", "F"}};
    vector<Edge> campus = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}};
    check("T", tree);
    check("T without C-F", vector<Edge>(tree.begin(), tree.end() - 1));
    check("Campus map", campus);

    // Adding any edge to a tree closes exactly one cycle: the tree path between its ends plus the new edge
    vector<string> ignored;
    auto parent = bfsParents(tree, "D", ignored);
    vector<string> path;
    for (string x = "F"; !x.empty(); x = parent[x]) path.push_back(x);
    reverse(path.begin(), path.end());
    cout << "Tree path D to F: " << join(path, " -> ") << "\n";
    path.push_back("D");
    cout << "Adding D-F closes the cycle: " << join(path, " -> ") << "\n";

    // BFS keeps only the edge that discovered each vertex: a spanning tree of the campus map
    vector<string> spanning;
    bfsParents(campus, "A", spanning);
    cout << "BFS spanning tree of the campus map: " << join(spanning, ", ") << " (" << spanning.size() << " = " << VERTS.size() << " - 1 edges)\n";
}

