// Counting and probability helpers, each formula checked against brute force
#include <bitset>
#include <cstdio>
#include <string>

long long factorial(int n) {
    long long ans = 1;
    for (int i = 2; i <= n; i++) ans *= i;
    return ans;
}

long long permutations(int n, int k) {
    long long ans = 1;
    for (int i = 0; i < k; i++) ans *= n - i;  // n * (n-1) * ... * (n-k+1) = n!/(n-k)!
    return ans;
}

// Multiplicative formula: each partial result is itself a binomial coefficient, so the division is exact
long long nCr(int n, int r) {
    long long ans = 1;
    for (int i = 1; i <= r; i++) ans = ans * (n - r + i) / i;
    return ans;
}

int main() {
    const int n = 5, r = 2;
    std::printf("5! = %lld\n", factorial(5));
    std::printf("P(5,2) = 5!/3! = %lld\n", permutations(n, r));
    std::printf("C(5,2) = %lld\n", nCr(n, r));

    int subsets = 0;  // brute force: count 5-bit masks with exactly two 1-bits
    for (int mask = 0; mask < (1 << n); mask++) {
        if (std::bitset<n>(mask).count() == r) subsets++;
    }
    std::printf("brute force: %d two-element subsets of {1..5}\n", subsets);
    std::printf("order matters: P(5,2) = C(5,2) * 2! = %lld * %lld = %lld\n", nCr(n, r), factorial(r),
                nCr(n, r) * factorial(r));

    std::string twoHeads;
    int favorable = 0;
    for (int i = 0; i < 8; i++) {
        std::string s;
        for (int bit = 2; bit >= 0; bit--) s += ((i >> bit) & 1) ? 'H' : 'T';
        if (std::bitset<3>(i).count() == 2) {
            twoHeads += (favorable ? " " : "") + s;
            favorable++;
        }
    }
    std::printf("exactly 2 heads among the 8 outcomes of 3 flips: %s\n", twoHeads.c_str());
    std::printf("P(exactly 2 heads in 3 fair flips) = %d/8 = %.4f\n", favorable, favorable / 8.0);
    std::printf("binomial formula: C(3,2) * (1/2)^2 * (1/2)^1 = %lld/8\n", nCr(3, 2));
}

