const factorial = (n) => {
  let ans = 1;
  for (let i = 2; i <= n; i++) ans *= i;
  return ans;
};

const permutations = (n, k) => {
  let ans = 1;
  for (let i = 0; i < k; i++) ans *= n - i; // n * (n-1) * ... * (n-k+1) = n!/(n-k)!
  return ans;
};

// Multiplicative formula: each partial result is itself a binomial coefficient, so the division is exact
const nCr = (n, r) => {
  let ans = 1;
  for (let i = 1; i <= r; i++) ans = (ans * (n - r + i)) / i;
  return ans;
};

const bitCount = (x) => x.toString(2).split('').filter((b) => b === '1').length;

const n = 5;
const r = 2;
console.log(`5! = ${factorial(5)}`);
console.log(`P(5,2) = 5!/3! = ${permutations(n, r)}`);
console.log(`C(5,2) = ${nCr(n, r)}`);
let subsets = 0; // brute force: count 5-bit masks with exactly two 1-bits
for (let mask = 0; mask < 1 << n; mask++) {
  if (bitCount(mask) === r) subsets++;
}
console.log(`brute force: ${subsets} two-element subsets of {1..5}`);
console.log(`order matters: P(5,2) = C(5,2) * 2! = ${nCr(n, r)} * ${factorial(r)} = ${nCr(n, r) * factorial(r)}`);

const twoHeads = [];
for (let i = 0; i < 8; i++) {
  const s = i.toString(2).padStart(3, '0').replace(/1/g, 'H').replace(/0/g, 'T');
  if (bitCount(i) === 2) twoHeads.push(s);
}
console.log(`exactly 2 heads among the 8 outcomes of 3 flips: ${twoHeads.join(' ')}`);
console.log(`P(exactly 2 heads in 3 fair flips) = ${twoHeads.length}/8 = ${(twoHeads.length / 8).toFixed(4)}`);
console.log(`binomial formula: C(3,2) * (1/2)^2 * (1/2)^1 = ${nCr(3, 2)}/8`);

