import java.util.ArrayList;
import java.util.List;

// k-permutations: ordered arrangements of k distinct items, listed by backtracking and counted by formula
public class PermutationsEnumeration {
    // Choose each position in turn from the letters not used yet
    static void arrange(String letters, int k, StringBuilder current, boolean[] used, List<String> out) {
        if (current.length() == k) {
            out.add(current.toString());
            return;
        }
        for (int i = 0; i < letters.length(); i++) {
            if (used[i]) continue;
            used[i] = true;
            current.append(letters.charAt(i));
            arrange(letters, k, current, used, out);
            current.deleteCharAt(current.length() - 1); // undo the choice before trying the next letter
            used[i] = false;
        }
    }

    static List<String> kPermutations(String letters, int k) {
        List<String> out = new ArrayList<>();
        arrange(letters, k, new StringBuilder(), new boolean[letters.length()], out);
        return out;
    }

    static long factorial(int n) {
        long ans = 1;
        for (int i = 2; i <= n; i++) ans *= i;
        return ans;
    }

    public static void main(String[] args) {
        String letters = "ABCD";
        int n = letters.length();
        System.out.println("2-permutations of ABCD: " + String.join(" ", kPermutations(letters, 2)));
        for (int k = 1; k <= n; k++) {
            int brute = kPermutations(letters, k).size();
            long formula = factorial(n) / factorial(n - k);
            System.out.println("k=" + k + ": brute force " + brute + ", P(4," + k + ") = 4!/" + (n - k) + "! = "
                    + formula);
        }
        // With repetition, every position has all n choices: n^k
        List<String> withRepetition = new ArrayList<>();
        for (char a : letters.toCharArray()) {
            for (char b : letters.toCharArray()) withRepetition.add("" + a + b);
        }
        System.out.println("2-letter strings with repetition (AA allowed): " + withRepetition.size() + " = 4^2");
    }
}

