// k-permutations: ordered arrangements of k distinct items, listed by backtracking and counted by formula
#include <iostream>
#include <string>
#include <vector>

// Choose each position in turn from the letters not used yet
void arrange(const std::string& letters, size_t k, std::string& current, std::vector<bool>& used,
             std::vector<std::string>& out) {
    if (current.size() == k) {
        out.push_back(current);
        return;
    }
    for (size_t i = 0; i < letters.size(); i++) {
        if (used[i]) continue;
        used[i] = true;
        current.push_back(letters[i]);
        arrange(letters, k, current, used, out);
        current.pop_back();  // undo the choice before trying the next letter
        used[i] = false;
    }
}

std::vector<std::string> kPermutations(const std::string& letters, size_t k) {
    std::vector<std::string> out;
    std::string current;
    std::vector<bool> used(letters.size(), false);
    arrange(letters, k, current, used, out);
    return out;
}

long long factorial(int n) {
    long long ans = 1;
    for (int i = 2; i <= n; i++) ans *= i;
    return ans;
}

int main() {
    const std::string letters = "ABCD";
    const int n = static_cast<int>(letters.size());
    std::cout << "2-permutations of ABCD:";
    for (const auto& s : kPermutations(letters, 2)) std::cout << " " << s;
    std::cout << "\n";
    for (int k = 1; k <= n; k++) {
        size_t brute = kPermutations(letters, k).size();
        long long formula = factorial(n) / factorial(n - k);
        std::cout << "k=" << k << ": brute force " << brute << ", P(4," << k << ") = 4!/" << (n - k)
                  << "! = " << formula << "\n";
    }
    // With repetition, every position has all n choices: n^k
    std::vector<std::string> withRepetition;
    for (char a : letters) {
        for (char b : letters) withRepetition.push_back({a, b});
    }
    std::cout << "2-letter strings with repetition (AA allowed): " << withRepetition.size() << " = 4^2\n";
}

