function kPermutations(letters, k) {
  const out = [];
  const used = new Array(letters.length).fill(false);
  // Choose each position in turn from the letters not used yet
  const arrange = (current) => {
    if (current.length === k) {
      out.push(current);
      return;
    }
    for (let i = 0; i < letters.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      arrange(current + letters[i]);
      used[i] = false; // undo the choice before trying the next letter
    }
  };
  arrange('');
  return out;
}

