import java.util.ArrayList;
import java.util.List;

// k-combinations: unordered selections, listed by recursion and counted with C(n, k)
public class CombinationsEnumeration {
    // Only pick letters after position start, so each set appears once, in increasing order
    static void choose(String letters, int k, int start, String current, List<String> out) {
        if (current.length() == k) {
            out.add(current);
            return;
        }
        for (int i = start; i < letters.length(); i++) {
            choose(letters, k, i + 1, current + letters.charAt(i), out);
        }
    }

    static List<String> combinations(String letters, int k) {
        List<String> out = new ArrayList<>();
        choose(letters, k, 0, "", out);
        return out;
    }

    static long nCr(int n, int k) {
        long ans = 1;
        for (int i = 1; i <= k; i++) ans = ans * (n - k + i) / i; // exact at every step
        return ans;
    }

    public static void main(String[] args) {
        String letters = "ABCDE";
        List<String> pairs = combinations(letters, 2);
        System.out.println("2-combinations of ABCDE: " + String.join(" ", pairs));
        System.out.println("count = " + pairs.size() + ", C(5,2) = 5!/(2!*3!) = " + nCr(5, 2));
        System.out.println("each has 2! orders, so " + pairs.size() + " * 2 = " + pairs.size() * 2 + " = P(5,2)");

        StringBuilder brute = new StringBuilder(), formula = new StringBuilder();
        for (int k = 0; k <= 5; k++) {
            brute.append(" ").append(combinations(letters, k).size());
            formula.append(" ").append(nCr(5, k));
        }
        System.out.println("k = 0..5 brute force:" + brute);
        System.out.println("k = 0..5 C(5,k):     " + formula);
        System.out.println("symmetry: C(5,2) = C(5,3) = " + nCr(5, 3) + " (choosing 2 to take = choosing 3 to leave)");
        System.out.println("committees of 3 from 10 students: " + combinations("ABCDEFGHIJ", 3).size()
                + " = C(10,3) = " + nCr(10, 3));
    }
}

