import java.util.StringJoiner;

// Binomial coefficients from Pascal's rule C(n,k) = C(n-1,k-1) + C(n-1,k), with no factorials
public class PascalTriangleBinomial {
    static final int N = 60;

    static long nCr(int n, int k) {
        long ans = 1;
        for (int i = 1; i <= k; i++) ans = ans * (n - k + i) / i; // stays below 2^63 for n <= 60
        return ans;
    }

    public static void main(String[] args) {
        long[][] c = new long[N + 1][N + 1];
        for (int n = 0; n <= N; n++) {
            c[n][0] = c[n][n] = 1; // one way to choose nothing, one way to choose everything
            for (int k = 1; k < n; k++) c[n][k] = c[n - 1][k - 1] + c[n - 1][k];
        }
        for (int n = 0; n <= 6; n++) {
            StringJoiner row = new StringJoiner(" ");
            long sum = 0;
            for (int k = 0; k <= n; k++) {
                row.add(String.valueOf(c[n][k]));
                sum += c[n][k];
            }
            // Row n sums to 2^n: each subset of an n-set has some size k
            System.out.printf("row %d: %-18s sum = %d = 2^%d%n", n, row, sum, n);
        }
        System.out.println("Pascal's rule: C(6,2) = C(5,1) + C(5,2) = " + c[5][1] + " + " + c[5][2] + " = " + c[6][2]);
        System.out.println("symmetry: C(6,2) = C(6,4) = " + c[6][4]);
        System.out.println("C(30,15): Pascal table " + c[30][15] + ", multiplicative " + nCr(30, 15));
        System.out.println("C(60,30): Pascal table " + c[60][30] + ", multiplicative " + nCr(60, 30));
        System.out.println("(60! itself has 82 digits, so n!/(k!(n-k)!) cannot work in 64 bits)");
    }
}

