  constructor(num, den) {
    const g = gcd(num, den); // always store in lowest terms
    this.num = num / g;
    this.den = den / g;
  }
  plus(o) { return new Frac(this.num * o.den + o.num * this.den, this.den * o.den); }
  minus(o) { return new Frac(this.num * o.den - o.num * this.den, this.den * o.den); }
  times(o) { return new Frac(this.num * o.num, this.den * o.den); }
  equals(o) { return this.num === o.num && this.den === o.den; }
